                                    function,
                                    &mut incoming[entry.0 as usize],
                                    latched,
                                    budget,
                                );
                                if insertions.failed {
                                    return Err(insertions.failure().into());
                                }
                            } else {
                                lexical_flow::check_latch(
                                    function,
                                    auth,
                                    exit,
                                    &latched,
                                    &loop_entries,
                                )?;
